func (d *db) Restore(ctx context.Context, path string) error {
 if path == "" { return errors.New("backup file is required") }
 absolute, err := filepath.Abs(path)
 if err != nil { return err }
 if _, err := os.Stat(absolute); err != nil { return err }
 if Path != ":memory:" {
  live, err := filepath.Abs(Path)
  if err == nil && live == absolute { return errors.New("backup file is the live database") }
  if liveInfo, err := os.Stat(live); err == nil {
   if sourceInfo, err := os.Stat(absolute); err == nil && os.SameFile(liveInfo, sourceInfo) { return errors.New("backup file is the live database") }
  }
