 sourceURL := (&url.URL{Scheme:"file", Path:absolute, RawQuery:"mode=ro"}).String()
 source, err := sql.Open(Driver, sourceURL)
 if err != nil { return err }
 defer source.Close()
 var result string
 if err := source.QueryRowContext(ctx, "PRAGMA quick_check").Scan(&result); err != nil { return fmt.Errorf("invalid backup: %w", err) }
 if result != "ok" { return fmt.Errorf("invalid backup: %s", result) }
 if err := copySQLite(ctx, source, d.writeDB); err != nil { return fmt.Errorf("restore database: %w", err) }
 return nil
}

func copySQLite(ctx context.Context, source, destination *sql.DB) error {
 src, err := source.Conn(ctx)
 if err != nil { return err }
 defer src.Close()
 dst, err := destination.Conn(ctx)
 if err != nil { return err }
 defer dst.Close()
 return src.Raw(func(srcDriver any) error {
  sqliteSource, ok := srcDriver.(*sqlite3.SQLiteConn)
  if !ok { return errors.New("source is not SQLite") }
  return dst.Raw(func(dstDriver any) error {
   sqliteDestination, ok := dstDriver.(*sqlite3.SQLiteConn)
   if !ok { return errors.New("destination is not SQLite") }
   backup, err := sqliteDestination.Backup("main", sqliteSource, "main")
   if err != nil { return err }
   for {
    if err := ctx.Err(); err != nil { _ = backup.Finish(); return err }
    done, err := backup.Step(100)
    if err != nil { _ = backup.Finish(); return err }
    if done { return backup.Finish() }
    time.Sleep(10*time.Millisecond)
   }
  })
 })
}

