 dir := conf.Server.Backup.Path
 if dir == "" { return 0, errors.New("backup.path is empty") }
 if conf.Server.Backup.Count < 0 { return 0, errors.New("backup.count cannot be negative") }
 entries, err := os.ReadDir(dir)
 if err != nil { return 0, err }
 var names []string
 for _, entry := range entries {
  name := entry.Name()
  if entry.IsDir() || !strings.HasPrefix(name, backupPrefix) || !strings.HasSuffix(name, backupSuffix) { continue }
  timestamp := strings.TrimSuffix(strings.TrimPrefix(name, backupPrefix), backupSuffix)
