		return err
	}
	defer src.Close()
	dst, err := destination.Conn(ctx)
	if err != nil {
		return err
	}
	defer dst.Close()
	return src.Raw(func(srcDriver any) error {
		sqliteSource, ok := srcDriver.(*sqlite3.SQLiteConn)
		if !ok {
			return errors.New("source is not SQLite")
		}
		return dst.Raw(func(dstDriver any) error {
			sqliteDestination, ok := dstDriver.(*sqlite3.SQLiteConn)
			if !ok {
				return errors.New("destination is not SQLite")
			}
			backup, err := sqliteDestination.Backup("main", sqliteSource, "main")
			if err != nil {
				return err
			}
			for {
				if err := ctx.Err(); err != nil {
					_ = backup.Finish()
					return err
				}
				done, err := backup.Step(100)
				if err != nil {
					_ = backup.Finish()
					return err
				}
				if done {
					return backup.Finish()
				}
				time.Sleep(10 * time.Millisecond)
			}
		})
	})
}

func (d *db) Prune(ctx context.Context) (int, error) { return prune(ctx) }

func prune(ctx context.Context) (int, error) {
	dir := conf.Server.Backup.Path
	if dir == "" {
		return 0, errors.New("backup.path is empty")
	}
	if conf.Server.Backup.Count < 0 {
		return 0, errors.New("backup.count cannot be negative")
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return 0, err
	}
	var names []string
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasPrefix(name, backupPrefix) || !strings.HasSuffix(name, backupSuffix) {
			continue
		}
		timestamp := strings.TrimSuffix(strings.TrimPrefix(name, backupPrefix), backupSuffix)
		if _, err := time.Parse(backupTimestamp, timestamp); err == nil {
			names = append(names, name)
		}
	}
	sort.Sort(sort.Reverse(sort.StringSlice(names)))
	removed := 0
	for _, name := range names[min(conf.Server.Backup.Count, len(names)):] {
		if err := ctx.Err(); err != nil {
			return removed, err
		}
		if err := os.Remove(filepath.Join(dir, name)); err != nil {
			return removed, err
		}
		removed++
	}
	return removed, nil
}
package cmd

import (
	"bufio"
	"errors"
	"fmt"
	"strings"

	"github.com/navidrome/navidrome/conf"
	"github.com/navidrome/navidrome/db"
	"github.com/spf13/cobra"
)

func init() {
	backupCmd := &cobra.Command{Use: "backup", Short: "Manage database backups"}
	create := &cobra.Command{Use: "create", Short: "Create a database backup", Args: cobra.NoArgs, RunE: func(cmd *cobra.Command, _ []string) error {
		path, err := db.Db().Backup(cmd.Context())
		if err != nil {
			return err
		}
		_, err = fmt.Fprintln(cmd.OutOrStdout(), path)
		return err
	}}
	prune := &cobra.Command{Use: "prune", Short: "Delete old database backups", Args: cobra.NoArgs, RunE: func(cmd *cobra.Command, _ []string) error {
		force, _ := cmd.Flags().GetBool("force")
		if conf.Server.Backup.Count == 0 && !force {
			if !confirmBackupAction(cmd, "Delete all database backups") {
				return errors.New("backup pruning cancelled")
			}
		}
		count, err := db.Db().Prune(cmd.Context())
		if err != nil {
			return err
		}
		_, err = fmt.Fprintf(cmd.OutOrStdout(), "Pruned %d backups\n", count)
		return err
	}}
	prune.Flags().Bool("force", false, "skip confirmation")
	restore := &cobra.Command{Use: "restore", Short: "Restore a database backup", Args: cobra.NoArgs, RunE: func(cmd *cobra.Command, _ []string) error {
		path, _ := cmd.Flags().GetString("backup-file")
		force, _ := cmd.Flags().GetBool("force")
		if !force && !confirmBackupAction(cmd, "Replace the current database with "+path) {
			return errors.New("database restore cancelled")
		}
		if err := db.Db().Restore(cmd.Context(), path); err != nil {
			return err
		}
		_, err := fmt.Fprintln(cmd.OutOrStdout(), "Database restored")
		return err
	}}
	restore.Flags().String("backup-file", "", "backup database file to restore")
	_ = restore.MarkFlagRequired("backup-file")
	restore.Flags().Bool("force", false, "skip confirmation")
	backupCmd.AddCommand(create, prune, restore)
	rootCmd.AddCommand(backupCmd)
}

func confirmBackupAction(cmd *cobra.Command, action string) bool {
	_, _ = fmt.Fprintf(cmd.OutOrStdout(), "%s? Type yes to continue: ", action)
	line, err := bufio.NewReader(cmd.InOrStdin()).ReadString('\n')
	return err == nil && strings.EqualFold(strings.TrimSpace(line), "yes")
}

